      if (v.saturate !== "" && v.saturate != null && Number(v.saturate) !== 1) parts.push("saturate(" + v.saturate + ")");
      if (v.hue && parseFloat(v.hue)) parts.push("hue-rotate(" + v.hue + (String(v.hue).match(/deg/i) ? "" : "deg") + ")");
