      if (!r || !list) return;
      const i = Number(b.closest("[data-fx-index]")?.dataset.fxIndex);
      if (!Number.isFinite(i)) return;
      app.commit();
      list.splice(i, 1);
      touch();
      app.refreshRightPanel();
